    CREATE INDEX "IX_PaymentEntries_FeeRecordId" ON "PaymentEntries" ("FeeRecordId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260725072552_InitialCreate') THEN
    CREATE UNIQUE INDEX "IX_Students_RollNo" ON "Students" ("RollNo");
    END IF;
END $EF$;

DO $EF$
BEGIN
